class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        res, q = [], deque([root] if root else [])
        while q:
            res.append(q[-1].val)           # 这一层最右边的节点
            for _ in range(len(q)):
                node = q.popleft()
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
        return res

class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        res = []
        def dfs(node, depth):
            if node:
                if depth == len(res):
                    res.append(node.val)
                dfs(node.right, depth + 1)
                dfs(node.left, depth + 1)
        dfs(root, 0)
        return res

